import{_ as l,C as a,o as n,c as h,j as e,a as t,E as o,ah as r}from"./chunks/framework.BpF7DVZ1.js";const v=JSON.parse('{"title":"代码视图","description":"","frontmatter":{},"headers":[],"relativePath":"components/code-view.md","filePath":"components/code-view.md","lastUpdated":1788635489000}'),s={name:"components/code-view.md"},p={id:"代码视图",tabindex:"-1"};function b(g,d,u,m,x,f){const i=a("Badge"),c=a("XhDemo");return n(),h("div",null,[e("h1",p,[d[0]||(d[0]=t("代码视图 ",-1)),o(i,{type:"info",text:"code-view"}),d[1]||(d[1]=t()),d[2]||(d[2]=e("a",{class:"header-anchor",href:"#代码视图","aria-label":'Permalink to "代码视图 <Badge type="info" text="code-view" />"'},"​",-1))]),d[3]||(d[3]=r('<p>一段代码的逐行呈现：行号、指定行高亮、超长折叠、文件名，可选语法着色，支持流式追加时的未闭合状态。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>AI 回复、文档、评审意见里展示一段代码，需要行号或要点出某几行。</li><li>代码是流式生成的，需要边来边渲，闭合之后再着色。</li><li>一段代码很长，默认只想露出前若干行。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>只是一小段行内标识：用<a href="./typography">排印</a>的 <code>code</code> 形态。</li><li>展示的是运行日志：用<a href="./log">日志</a>。</li><li>要展示改动前后：用<a href="./diff-view">差异视图</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>逐行切分在连接层完成。一个记号可以横跨多行（未闭合的字符串与块注释就是这样）， 所以行号与高亮行不是皮肤能反推出来的东西。</li><li><code>complete</code> 标出这段代码是否已经写完。未闭合时默认不着色——半截代码的词法本来就不稳， 每来一个字符整块变一次色比不着色更糟。</li><li><code>highlighter</code> 是一个着色端口，接哪个着色器由宿主决定；它返回 <code>null</code> 是合法结果，退回纯文本。 适配器默认接 <code>@xihan-ui/code-highlight</code>，那是可选 peer：装了它自动着色，没装就一路纯文本。</li><li>行号由皮肤用 <code>attr()</code> 画出来，因此<strong>复制代码不会带上行号</strong>，读屏也不会逐行念数字。</li><li><code>clamped</code> 是纯受控的：折叠态通常由外部「全部展开 / 全部折叠」统一持有，内建一份只会跟它打架。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>代码原文由宿主给，组件切出逐行结构并铺记号；渲了文件名它就成为代码块的可访问名</p>',10)),o(c,{src:"code-view/01-basic"}),d[4]||(d[4]=e("h3",{id:"行号与高亮行",tabindex:"-1"},[t("行号与高亮行 "),e("a",{class:"header-anchor",href:"#行号与高亮行","aria-label":'Permalink to "行号与高亮行"'},"​")],-1)),d[5]||(d[5]=e("p",null,"行号由皮肤画上去，复制代码不会带上它；高亮行按行号写，与 startLine 对齐",-1)),o(c,{src:"code-view/02-line-numbers"}),d[6]||(d[6]=e("h3",{id:"折叠超长代码",tabindex:"-1"},[t("折叠超长代码 "),e("a",{class:"header-anchor",href:"#折叠超长代码","aria-label":'Permalink to "折叠超长代码"'},"​")],-1)),d[7]||(d[7]=e("p",null,"clamped 是纯受控的：组件只发意图，落不落由宿主决定，好让「全部展开」这类操作统一持有",-1)),o(c,{src:"code-view/03-fold"}),d[8]||(d[8]=e("h3",{id:"流式追加",tabindex:"-1"},[t("流式追加 "),e("a",{class:"header-anchor",href:"#流式追加","aria-label":'Permalink to "流式追加"'},"​")],-1)),d[9]||(d[9]=e("p",null,"代码还在写的时候默认不着色：半截代码的词法本来就不稳，每来一个字符整块变色比不着色更糟",-1)),o(c,{src:"code-view/04-streaming"}),d[10]||(d[10]=e("h3",{id:"头部内建复制",tabindex:"-1"},[t("头部内建复制 "),e("a",{class:"header-anchor",href:"#头部内建复制","aria-label":'Permalink to "头部内建复制"'},"​")],-1)),d[11]||(d[11]=e("p",null,"复制交给剪贴板：把它放进头部条，用几个槽把描边按钮压成安静形态，1500 毫秒后自己回落",-1)),o(c,{src:"code-view/05-copy"}),d[12]||(d[12]=e("h3",{id:"着色端口",tabindex:"-1"},[t("着色端口 "),e("a",{class:"header-anchor",href:"#着色端口","aria-label":'Permalink to "着色端口"'},"​")],-1)),d[13]||(d[13]=e("p",null,"着色是可换的端口：认不出的语言退回纯文本，接自己的实现组件侧一行不用改，传 null 则整个关掉",-1)),o(c,{src:"code-view/06-highlighter"}),d[14]||(d[14]=e("h3",{id:"流式期间也着色",tabindex:"-1"},[t("流式期间也着色 "),e("a",{class:"header-anchor",href:"#流式期间也着色","aria-label":'Permalink to "流式期间也着色"'},"​")],-1)),d[15]||(d[15]=e("p",null,"未闭合默认不着色；真要看着色就打开 highlight-while-streaming，同一段半截代码的两种呈现摆在一起",-1)),o(c,{src:"code-view/07-streaming-highlight"}),d[16]||(d[16]=e("h3",{id:"尺寸",tabindex:"-1"},[t("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),d[17]||(d[17]=e("p",null,"size 换字号、行高与内边距三档，行号槽与折叠钮跟着一起走",-1)),o(c,{src:"code-view/08-size"}),d[18]||(d[18]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-code-view&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhCodeViewCode</code> <code>XhCodeViewFilename</code> <code>XhCodeViewFoldTrigger</code> <code>XhCodeViewHeader</code> <code>XhCodeViewLangLabel</code> <code>XhCodeViewPre</code> <code>XhCodeViewRoot</code></td></tr><tr><td>组合式函数</td><td><code>useCodeView</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/code-view.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;code-view&quot;</code>：<strong><code>root</code></strong> · <code>header</code> · <code>filename</code> · <code>lang-label</code> · <strong><code>pre</code></strong> · <strong><code>code</code></strong> · <code>line</code> · <code>line-number</code> · <code>line-content</code> · <code>token</code> · <code>fold-trigger</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>clamp</code></td><td><code>number</code></td><td></td><td>超过这么多行才算可折叠。</td></tr><tr><td><code>clamped</code></td><td><code>boolean</code></td><td></td><td>折叠态，纯受控——没有 defaultClamped，要非受控就套 collapsible。</td></tr><tr><td><code>code</code></td><td><code>string</code></td><td>是</td><td></td></tr><tr><td><code>complete</code></td><td><code>boolean</code></td><td></td><td>代码是否已闭合，未闭合时按行数预撑高度且默认不着色。</td></tr><tr><td><code>filename</code></td><td><code>string</code></td><td></td><td>文件名，渲染在 header 里；渲染出来之后它就是 pre 的可访问名。</td></tr><tr><td><code>highlighter</code></td><td><code>HighlighterPort</code></td><td></td><td>着色实现。不给就是纯文本，给了也允许它返回 null（语言不认识之类），同样退回纯文本。 未闭合的块默认不着色，见 {@link highlightWhileStreaming}。</td></tr><tr><td><code>highlightLines</code></td><td><code>string | readonly number[]</code></td><td></td><td>要高亮的行号，写成 <code>&#39;3,7-9&#39;</code> 或行号数组；非法片段丢弃不报错。</td></tr><tr><td><code>highlightWhileStreaming</code></td><td><code>boolean</code></td><td></td><td>块还没闭合时也着色，默认 false。 默认关是因为半截代码的词法本来就不稳——引号、括号随时会配上， 每来一个 token 整块变一次色，看着比不着色更糟。</td></tr><tr><td><code>labelled</code></td><td><code>boolean</code></td><td></td><td>作者渲染了 filename 部件时置真，由适配器统计而不是看 filename 有没有值。 为假时 pre 用 translations.code 兜底——指向一个没渲出来的 id 会让读屏读空。</td></tr><tr><td><code>lang</code></td><td><code>string</code></td><td></td><td>围栏语言标注，空白一律落 plaintext。</td></tr><tr><td><code>lineNumbers</code></td><td><code>boolean</code></td><td></td><td>渲染行号槽。</td></tr><tr><td><code>onClampToggle</code></td><td><code>(details: CodeViewClampToggleDetails) =&gt; void</code></td><td></td><td>折叠态翻面的意图回调；clamped 是纯受控的，落不落由宿主决定。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg。</td></tr><tr><td><code>startLine</code></td><td><code>number</code></td><td></td><td>首行的行号，默认 1；摘录与 patch 片段要用。</td></tr><tr><td><code>translations</code></td><td><code>Partial&lt;CodeViewTranslations&gt;</code></td><td></td><td></td></tr><tr><td><code>wrap</code></td><td><code>boolean</code></td><td></td><td>长行自动换行，默认关（长行横向滚动）。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>clamp-toggle</code></td><td><code>CustomEvent</code></td><td>折叠态翻面的意图；detail 为 <code>{ clamped: boolean }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhCodeViewCode</code></td><td><code>line</code></td><td><code>CodeViewLineSlotProps</code></td><td></td></tr><tr><td><code>XhCodeViewRoot</code></td><td><code>default</code></td><td><code>CodeViewRootSlotProps</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>对外可见的状态落在 <code>data-state</code> 上，写样式与断言都读它：</p><table tabindex="0"><thead><tr><th>部件</th><th>取值</th></tr></thead><tbody><tr><td><code>fold-trigger</code></td><td>&#39;closed&#39; | &#39;open&#39;</td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useCodeView</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>lang</code></td><td><code>string</code></td><td></td></tr><tr><td><code>lineCount</code></td><td><code>number</code></td><td></td></tr><tr><td><code>lines</code></td><td><code>readonly CodeLine[]</code></td><td>逐行切好的文本与记号片段。</td></tr><tr><td><code>lineNumberAt</code></td><td><code>(index: number) =&gt; number</code></td><td>每行的行号，与 lines 同序。</td></tr><tr><td><code>lineNumbers</code></td><td><code>boolean</code></td><td>是否渲染行号槽；适配器据此决定要不要建那个节点。</td></tr><tr><td><code>foldable</code></td><td><code>boolean</code></td><td>折叠可用：给了正数 clamp 且行数确实超过它。</td></tr><tr><td><code>clamped</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>setClamped</code></td><td><code>(next: boolean) =&gt; void</code></td><td>发一次折叠意图；与当前态相同时不发。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getHeaderProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getFilenameProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLangLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getPreProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getCodeProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineProps</code></td><td><code>(props: CodeViewLineProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineNumberProps</code></td><td><code>(props: CodeViewLineProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLineContentProps</code></td><td><code>(props: CodeViewLineProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getTokenProps</code></td><td><code>(token: CodeToken) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getFoldTriggerProps</code></td><td><code>() =&gt; T[&#39;button&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/WCAG21/Techniques/general/G202" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code></td><td>代码块在 Tab 序列中</td><td>&lt;pre&gt; 自身可聚焦，随后方向键的横向滚动交给浏览器，组件不接管</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>焦点在折叠按钮上</td><td>翻面折叠态并发出意图；组件只接 click，按键走原生 button 的默认行为</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>lang-label</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>pre</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr><tr><td><code>line-number</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>fold-trigger</code></td><td><code>aria-controls</code></td><td><code>pre</code> 部件的 id</td></tr><tr><td><code>fold-trigger</code></td><td><code>aria-expanded</code></td><td>&#39;false&#39; | &#39;true&#39;</td></tr><tr><td><code>fold-trigger</code></td><td><code>aria-label</code></td><td>props.translations?.expand | props.translations?.collapse</td></tr></tbody></table><ul><li><code>pre</code> 可聚焦并带可访问名：渲了文件名就指向它，没渲就用 <code>translations.code</code> 兜底。</li><li>折叠按钮带 <code>aria-expanded</code> 与 <code>aria-controls</code>，指向 <code>pre</code>。</li><li>语言角标与行号槽都对读屏隐藏，它们是装饰不是内容。</li></ul><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/code-view.css</code> 按部件选择：<code>[data-scope=&quot;code-view&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-clamped</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-complete</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-digits</code></td><td>String(Math.min( String(lineNumberAt(lineCount - 1)).…</td></tr><tr><td><code>root</code></td><td><code>data-foldable</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-lang</code></td><td>props.lang?.trim() || CODE_VIEW_FALLBACK_LANG</td></tr><tr><td><code>root</code></td><td><code>data-line-numbers</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>pre</code></td><td><code>data-complete</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>pre</code></td><td><code>data-wrap</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>code</code></td><td><code>data-lang</code></td><td>props.lang?.trim() || CODE_VIEW_FALLBACK_LANG</td></tr><tr><td><code>code</code></td><td><code>data-wrap</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>token</code></td><td><code>data-kind</code></td><td>token.kind</td></tr><tr><td><code>fold-trigger</code></td><td><code>data-state</code></td><td>&#39;closed&#39; | &#39;open&#39;</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-code-view-bg</code> · <code>--xh-code-view-border</code> · <code>--xh-code-view-comment-fg</code> · <code>--xh-code-view-fg</code> · <code>--xh-code-view-filename-fg</code> · <code>--xh-code-view-fold-bg-hover</code> · <code>--xh-code-view-fold-fg</code> · <code>--xh-code-view-fold-py</code> · <code>--xh-code-view-font</code> · <code>--xh-code-view-font-size</code> · <code>--xh-code-view-gutter-border</code> · <code>--xh-code-view-gutter-gap</code> · <code>--xh-code-view-header-border</code> · <code>--xh-code-view-header-fg</code> · <code>--xh-code-view-header-font-size</code> · <code>--xh-code-view-header-gap</code> · <code>--xh-code-view-header-h</code> · <code>--xh-code-view-header-px</code> · <code>--xh-code-view-header-py</code> · <code>--xh-code-view-highlight-bar</code> · <code>--xh-code-view-highlight-bg</code> · <code>--xh-code-view-highlight-fg</code> · <code>--xh-code-view-keyword-fg</code> · <code>--xh-code-view-keyword-weight</code> · <code>--xh-code-view-label-fg</code> · <code>--xh-code-view-label-font-size</code> · <code>--xh-code-view-line-height</code> · <code>--xh-code-view-number-fg</code> · <code>--xh-code-view-number-font-size</code> · <code>--xh-code-view-number-token-fg</code> · <code>--xh-code-view-punctuation-fg</code> · <code>--xh-code-view-px</code> · <code>--xh-code-view-py</code> · <code>--xh-code-view-radius</code> · <code>--xh-code-view-shadow</code> · <code>--xh-code-view-string-fg</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p><code>background</code> · <code>box-shadow</code> · <code>scale</code> 走 <code>transition</code> 过渡。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>与<a href="./clipboard">剪贴板</a>配合提供复制；要非受控的折叠就套<a href="./collapsible">折叠面板</a>。 把剪贴板三件放进 <code>header</code>，再用 <code>--xh-clipboard-copy-trigger-border: transparent</code>、 <code>--xh-clipboard-copy-trigger-bg: transparent</code>、<code>--xh-clipboard-copy-trigger-h: var(--xh-control-h-sm)</code> 三个槽把按钮压成头部里的安静形态。</li><li>内建词法只分注释、字符串、数字、关键字、标点五档。要区分函数名、类型名、属性名这类精度， 就自己实现 <code>highlighter</code> 端口（同步纯函数，接 Shiki 之类）传进来，皮肤按记号种类上色的那套照旧生效。</li><li>放进 AI 回复正文时由<a href="./markdown-stream">流式正文</a>把代码块交过来。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>标出语言：读者与着色器都需要它。</li><li>高亮行用来点出「看这里」，不要一次点亮半屏。</li><li>折叠阈值取十几行：再少读者每次都要展开，再多就失去了折叠的意义。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>把代码放进普通段落里：空白与换行会被折叠掉。</li><li>用行号当锚点做跳转：它是画上去的，DOM 里选不中。</li></ul>',45))])}const P=l(s,[["render",b]]);export{v as __pageData,P as default};
